import React, { useState, useEffect } from 'react';
import './Quiz.css';

export default function Result({ result, questions, onRetake }) {
  const [reviewMode, setReviewMode] = useState(false);

  if (!result) return <div>No result available</div>;

  const percentage = ((result.score / questions.length) * 100).toFixed(2);

  return (
    <div className="result-container">
      <div className="result-card">
        <h2>Quiz Complete!</h2>
        <div className="score-display">
          <h1>{result.score}/{questions.length}</h1>
          <p>Score: {percentage}%</p>
        </div>

        <button onClick={() => setReviewMode(!reviewMode)} className="review-btn">
          {reviewMode ? 'Hide Review' : 'Review Answers'}
        </button>

        {reviewMode && (
          <div className="review-section">
            <h3>Answer Review</h3>
            {questions.map((question, index) => {
              const userAnswer = result.answers[index];
              const isCorrect = userAnswer === question.correctIndex;
              return (
                <div key={question.id} className={`review-item ${isCorrect ? 'correct' : 'incorrect'}`}>
                  <p><strong>Q{index + 1}: {question.question}</strong></p>
                  <p>Your answer: {question.options[userAnswer] || 'Not answered'}</p>
                  {!isCorrect && <p className="correct-answer">Correct: {question.options[question.correctIndex]}</p>}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
